package com.hbm.blocks.machine.rbmk;
import com.hbm.tileentity.ModRBMKBlockEntities; import com.hbm.tileentity.machine.rbmk.*; import net.minecraft.core.BlockPos; import net.minecraft.world.level.block.entity.BlockEntityType; import net.minecraft.world.level.block.state.BlockState;
public class RBMKReflector extends RBMKBase { public final double reflection; public RBMKReflector(Properties properties) { this(properties, 1D); } public RBMKReflector(Properties properties, double reflection) { super(properties); this.reflection = reflection; } @Override protected BlockEntityType<? extends BlockEntityRBMKBase> beType() { return ModRBMKBlockEntities.RBMK_REFLECTOR.get(); } @Override protected BlockEntityRBMKBase createCore(BlockPos pos, BlockState state) { return new BlockEntityRBMKReflector(pos, state); } }
